const args=process.argv.slice(2);
function required(name:string):string {
  const index=args.indexOf('--'+name),value=args[index+1];
  if(index<0||!value||value.startsWith('--'))throw new Error('REQUIRED_ARGUMENT:'+name);
  return value;
}
